<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class PurchaseOrderItem extends Model {protected $fillable=['purchase_order_id','product_variant_id','quantity','unit_price','discount','tax','line_total']; protected $casts=['quantity'=>'decimal:3','unit_price'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','line_total'=>'decimal:2']; public function purchaseOrder():BelongsTo{return $this->belongsTo(PurchaseOrder::class);} public function productVariant():BelongsTo{return $this->belongsTo(ProductVariant::class);} public function receiptItems():HasMany{return $this->hasMany(GoodsReceiptItem::class);} }
